import re
import sys

values = {}
pattern = re.compile(
    r'\b(TMP|a|b|c|d)\s*<-\s*(?:(\d+)|'
    r'\(\s*(TMP|a|b|c|d)\s*\+\s*(\d+)\s*\)\s*mod\s*100)'
)

for match in pattern.finditer(sys.stdin.read()):
    variable, literal, source, increment = match.groups()
    if literal is not None:
        values[variable] = int(literal)
    else:
        values[variable] = (values[source] + int(increment)) % 100

print(
    f"a ?= {values['a']}; b ?= {values['b']}; "
    f"c ?= {values['c']}; d ?= {values['d']}; TMP ?= {values['TMP']};"
)
